import { ReactNode } from 'react';

export interface PageHeaderProps {
  title: string;
  /** linha descritiva abaixo do título (opcional em telas de listagem simples) */
  description?: ReactNode;
  /** botões/filtros à direita, alinhados à base do título */
  actions?: ReactNode;
}

/**
 * Cabeçalho padrão de toda tela: título (28px, tracking apertado) + descrição
 * curta + ações à direita. Use em TODAS as telas — é o que dá consistência
 * entre Visão geral, CRM, Agentes etc.
 */
export function PageHeader({ title, description, actions }: PageHeaderProps) {
  return (
    <div className="mb-7 flex items-end justify-between gap-4">
      <div>
        <h1 className="text-2xl font-semibold tracking-tight text-tx">{title}</h1>
        {description && <div className="mt-2 max-w-[640px] text-base text-tx3">{description}</div>}
      </div>
      {actions && <div className="flex flex-wrap items-center justify-end gap-2">{actions}</div>}
    </div>
  );
}
